begin;
create table if not exists public.organization_system_configuration(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,config_key text not null,config_value jsonb not null default 'null'::jsonb,description text,is_sensitive boolean not null default false,updated_by uuid references auth.users(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,config_key));
alter table public.organization_system_configuration enable row level security;
create policy "admins read configuration" on public.organization_system_configuration for select using(exists(select 1 from public.organization_members m where m.organization_id=organization_system_configuration.organization_id and m.user_id=auth.uid() and m.role in('owner','admin')));
create policy "admins manage configuration" on public.organization_system_configuration for all using(exists(select 1 from public.organization_members m where m.organization_id=organization_system_configuration.organization_id and m.user_id=auth.uid() and m.role in('owner','admin'))) with check(exists(select 1 from public.organization_members m where m.organization_id=organization_system_configuration.organization_id and m.user_id=auth.uid() and m.role in('owner','admin')));
commit;
